mapper.select:
SELECT
    a.*
FROM swm_inspection_plan a

    ${sqlMap.dsf}

        AND a.plan_code LIKE CONCAT('%', #{planCode}, '%')


        AND a.plan_name LIKE CONCAT('%', #{planName}, '%')


        AND a.frequency_days = #{frequencyDays}


        AND a.inspection_type = #{inspectionType}


        AND a.plan_status = #{planStatus}


        AND a.status = #{status}


        AND a.hazard_source_id = #{hazardSourceId}


        AND #{random} = #{random}


ORDER BY a.create_date DESC
